  x_c := x_c || pg_temp.consent('n-b1', x_b, 'openai');
  x_e := x_e || pg_temp.w(pg_temp.q_ex('n-b1', 'openai', 103));
  x_fb := pg_temp.effects(x_b);
  RETURN pg_temp.all_of(
    pg_temp.pass((SELECT bool_and(pg_temp.consented(c)) FROM jsonb_array_elements(x_c) c), 'consent ' || x_c::text),
    pg_temp.pass((SELECT bool_and(e = pg_temp.ok_answer()) FROM jsonb_array_elements(x_e) e), 'exchange ' || x_e::text),
    pg_temp.pass(x_f1 = '{"conns": ["active anthropic"], "tokens": 2, "codes_used": 1, "notices": ["anthropic false due"]}'::jsonb, 'first ' || x_f1::text),
    pg_temp.pass(x_f2 -> 'conns' = '["active anthropic"]' AND x_f2 -> 'notices' = '["anthropic false due", "anthropic true due"]', 'reconnect ' || x_f2::text),
    pg_temp.pass(x_fb = '{"conns": ["active openai"], "tokens": 2, "codes_used": 1, "notices": ["openai false due"]}'::jsonb, 'other user ' || x_fb::text));
END $c$;

-- ---------------------------------------------------------------- refused exchanges: answers unchanged, no notice
CREATE FUNCTION pg_temp.c_none() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE x_u uuid := pg_temp.id('C'); x_c jsonb := '[]'; x_r jsonb := '{}'; x_f jsonb;
BEGIN
  x_c := x_c || pg_temp.consent('n-c1', x_u, 'anthropic');
  x_r := x_r || jsonb_build_object('wrong_verifier', pg_temp.w(pg_temp.q_ex('n-c1', 'anthropic', 111, ver_o => pg_temp.ver('n-zz'))));
  x_r := x_r || jsonb_build_object('unknown_code', pg_temp.w(pg_temp.q_ex('n-c0', 'anthropic', 112, code_o => pg_temp.cdl('n-none'))));
  x_c := x_c || pg_temp.consent('n-c3', x_u, 'openai');
  x_r := x_r || jsonb_build_object('wrong_secret', pg_temp.w(pg_temp.q_ex('n-c3', 'openai', 114, sec_o => 'h66-wrong-secret')));
  x_r := x_r || jsonb_build_object('same_digests', pg_temp.w(pg_temp.q_ex('n-c3', 'openai', 114, rt_n => 114)));
  x_f := pg_temp.effects(x_u);
  RETURN pg_temp.all_of(
    pg_temp.pass((SELECT bool_and(pg_temp.consented(c)) FROM jsonb_array_elements(x_c) c), 'consent ' || x_c::text),
    -- 20261123170000: a verifier mismatch removes the pending connection and answers invalid_grant (the /*rejected*/
    -- branch, as in 20261118180000:121-134); an unknown code answers invalid_grant (:96-119); a wrong portal secret
    -- answers _mcp_refuse('invalid_grant') (:79-81); equal digests answer invalid_request (:82-85)
    pg_temp.pass(x_r = jsonb_build_object('wrong_verifier', pg_temp.refused('invalid_grant'), 'unknown_code', pg_temp.refused('invalid_grant'),
                                          'wrong_secret', pg_temp.refused('invalid_grant'), 'same_digests', pg_temp.refused('invalid_request')),
                 'answers ' || x_r::text),
    pg_temp.pass(x_f -> 'notices' = '[]' AND (x_f ->> 'tokens')::int = 0, 'effects ' || x_f::text));
END $c$;

-- ---------------------------------------------------------------- a notice that cannot be written fails the whole exchange
-- user B: an earlier active connection (with its notice), then the break, then a reconnect with code k that must raise
-- want_err and leave nothing (code unused, new connection pending, earlier connection and its tokens kept, no new
-- notice); then the break undone and the SAME code redeemed: ok and the second notice.
CREATE FUNCTION pg_temp.fail_case(k text, brk text, unbrk text, want_err text) RETURNS text LANGUAGE plpgsql AS $h$
DECLARE x_b uuid := pg_temp.id('B'); x_c0 jsonb; x_e0 jsonb; x_c jsonb; x_e jsonb; x_f jsonb; x_s jsonb; x_e2 jsonb; x_f2 jsonb; x_direct text; x_n bigint;
BEGIN
  x_c0 := pg_temp.consent(k || '-base', x_b, 'anthropic');
  x_e0 := pg_temp.w(pg_temp.q_ex(k || '-base', 'anthropic', 201));
  EXECUTE brk;
  -- the break acts: a direct INSERT (undone) raises want_err, or for the zero-row break writes no row
  BEGIN
    INSERT INTO public.ai_app_connect_notices (user_id, provider, replaced) VALUES (x_b, 'anthropic', false);
    GET DIAGNOSTICS x_n = ROW_COUNT;
    x_direct := 'rows=' || x_n;
    RAISE EXCEPTION USING ERRCODE = 'MX009';
  EXCEPTION WHEN SQLSTATE 'MX009' THEN NULL;
    WHEN OTHERS THEN x_direct := SQLSTATE;
  END;
  x_c := pg_temp.consent(k, x_b, 'anthropic');
  x_e := pg_temp.w(pg_temp.q_ex(k, 'anthropic', 202));
  x_f := pg_temp.effects(x_b);
  x_s := pg_temp.code_state(k);
  EXECUTE unbrk;
  x_e2 := pg_temp.w(pg_temp.q_ex(k, 'anthropic', 203));
  x_f2 := pg_temp.effects(x_b);
  RETURN pg_temp.all_of(
    pg_temp.pass(pg_temp.consented(x_c0) AND x_e0 = pg_temp.ok_answer(), 'earlier connection ' || x_c0::text || ' ' || coalesce(x_e0::text, 'null')),
    pg_temp.pass(x_direct = CASE WHEN want_err = 'MC004' THEN 'rows=0' ELSE want_err END, 'the break did not act on a direct INSERT: ' || coalesce(x_direct, 'null')),
    pg_temp.pass(pg_temp.consented(x_c), 'consent ' || x_c::text),
    pg_temp.pass(x_e ->> 'sqlerr' = want_err AND x_e ->> 'ok' IS NULL, 'exchange under the break did not raise ' || want_err || ': ' || coalesce(x_e::text, 'null')),
    pg_temp.pass(x_s = '{"used": false, "conn": "pending"}'::jsonb, 'code after the failed exchange ' || coalesce(x_s::text, 'null')),
    pg_temp.pass(x_f = '{"conns": ["active anthropic", "pending anthropic"], "tokens": 2, "codes_used": 1, "notices": ["anthropic false due"]}'::jsonb,
                 'state after the failed exchange ' || x_f::text),
    pg_temp.pass(x_e2 = pg_temp.ok_answer(), 'same code after the break was undone ' || coalesce(x_e2::text, 'null')),
    pg_temp.pass(x_f2 -> 'conns' = '["active anthropic"]' AND x_f2 -> 'notices' = '["anthropic false due", "anthropic true due"]', 'after the retry ' || x_f2::text));
END $h$;
CREATE FUNCTION pg_temp.c_fail_check() RETURNS text LANGUAGE sql AS $c$
  SELECT pg_temp.fail_case('n-f1', 'ALTER TABLE public.ai_app_connect_notices ADD CONSTRAINT h66_refuse CHECK (false) NOT VALID',
                           'ALTER TABLE public.ai_app_connect_notices DROP CONSTRAINT h66_refuse', '23514') $c$;
CREATE FUNCTION pg_temp.c_fail_deadlock() RETURNS text LANGUAGE sql AS $c$
  SELECT pg_temp.fail_case('n-f2', 'CREATE TRIGGER h66_t BEFORE INSERT ON public.ai_app_connect_notices FOR EACH ROW EXECUTE FUNCTION pg_temp.h66_raise_40p01()',
                           'DROP TRIGGER h66_t ON public.ai_app_connect_notices', '40P01') $c$;
CREATE FUNCTION pg_temp.c_fail_lock() RETURNS text LANGUAGE sql AS $c$
  SELECT pg_temp.fail_case('n-f3', 'CREATE TRIGGER h66_t BEFORE INSERT ON public.ai_app_connect_notices FOR EACH ROW EXECUTE FUNCTION pg_temp.h66_raise_55p03()',
                           'DROP TRIGGER h66_t ON public.ai_app_connect_notices', '55P03') $c$;
CREATE FUNCTION pg_temp.c_zero_row() RETURNS text LANGUAGE sql AS $c$
  SELECT pg_temp.fail_case('n-f4', 'CREATE TRIGGER h66_t BEFORE INSERT ON public.ai_app_connect_notices FOR EACH ROW EXECUTE FUNCTION pg_temp.h66_skip()',
                           'DROP TRIGGER h66_t ON public.ai_app_connect_notices', 'MC004') $c$;

-- ---------------------------------------------------------------- catalogue: the exchange and the notice table as the migration leaves them
CREATE FUNCTION pg_temp.c_catalogue() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE x jsonb; x_post text := 'ok';
BEGIN
  SELECT jsonb_build_object(
    'md5', md5(p.prosrc)::text, 'secdef', p.prosecdef, 'vol', p.provolatile::text, 'config', array_to_string(p.proconfig, ',')::text,
    'owner', pg_catalog.pg_get_userbyid(p.proowner)::text,
    'execute', (SELECT coalesce(jsonb_agg(DISTINCT a.grantee::regrole::text ORDER BY a.grantee::regrole::text), '[]') FROM aclexplode(p.proacl) a
                 WHERE a.privilege_type = 'EXECUTE' AND a.grantee <> 0),
    'public_execute', EXISTS (SELECT 1 FROM aclexplode(p.proacl) a WHERE a.grantee = 0))
    INTO x FROM pg_catalog.pg_proc p WHERE p.oid = to_regprocedure('public.mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)');
  x := x || (SELECT jsonb_build_object('t_owner', pg_catalog.pg_get_userbyid(c.relowner)::text, 't_rls', c.relrowsecurity, 't_force', c.relforcerowsecurity,
                                       't_triggers', (SELECT count(*) FROM pg_catalog.pg_trigger t WHERE t.tgrelid = c.oid AND NOT t.tgisinternal))
               FROM pg_catalog.pg_class c WHERE c.oid = 'public.ai_app_connect_notices'::regclass);
  BEGIN
    EXECUTE $mpq$DO $post4266$
DECLARE v jsonb;
BEGIN
  SELECT jsonb_build_object(
    'exchange', (SELECT md5(p.prosrc) = 'cc2810ee59467829f60d2a9e61455b6c' AND p.prosecdef AND p.provolatile = 'v'
                        AND array_to_string(p.proconfig, ',') = 'search_path=""' AND p.proowner = 'postgres'::regrole::oid
                        AND (SELECT array_agg(DISTINCT a.grantee::regrole::text ORDER BY a.grantee::regrole::text) FROM aclexplode(p.proacl) a
                              WHERE a.privilege_type = 'EXECUTE') = ARRAY['anon', 'postgres']
                        AND NOT EXISTS (SELECT 1 FROM aclexplode(p.proacl) a WHERE a.grantee = 0)
                   FROM pg_catalog.pg_proc p WHERE p.oid = 'public.mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)'::regprocedure),
    'table', (SELECT c.relowner = 'postgres'::regrole::oid AND c.relrowsecurity AND NOT c.relforcerowsecurity
                     AND NOT EXISTS (SELECT 1 FROM pg_catalog.pg_trigger t WHERE t.tgrelid = c.oid AND NOT t.tgisinternal)
                FROM pg_catalog.pg_class c WHERE c.oid = 'public.ai_app_connect_notices'::regclass),
    -- every provider a connection can have passes the notice table's provider CHECK: the two definitions are equal
    'provider_check_notices', (SELECT string_agg(pg_catalog.pg_get_constraintdef(k.oid)::text, ' & ' ORDER BY pg_catalog.pg_get_constraintdef(k.oid)::text)
                     FROM pg_catalog.pg_constraint k WHERE k.conrelid = 'public.ai_app_connect_notices'::regclass AND k.contype = 'c'
                      AND k.conkey = ARRAY[(SELECT a.attnum FROM pg_catalog.pg_attribute a WHERE a.attrelid = k.conrelid AND a.attname = 'provider')]::smallint[]),
    'provider_check_connections', (SELECT string_agg(pg_catalog.pg_get_constraintdef(k.oid)::text, ' & ' ORDER BY pg_catalog.pg_get_constraintdef(k.oid)::text)
                     FROM pg_catalog.pg_constraint k WHERE k.conrelid = 'public.mcp_connections'::regclass AND k.contype = 'c'
                      AND k.conkey = ARRAY[(SELECT a.attnum FROM pg_catalog.pg_attribute a WHERE a.attrelid = k.conrelid AND a.attname = 'provider')]::smallint[])) INTO v;
  IF (v ->> 'exchange')::boolean IS NOT TRUE OR (v ->> 'table')::boolean IS NOT TRUE
     OR v ->> 'provider_check_notices' IS NULL OR v ->> 'provider_check_notices' IS DISTINCT FROM v ->> 'provider_check_connections' THEN
    RAISE EXCEPTION 'BACKLOG-4266: post-check failed: %', v;
  END IF;
END
$post4266$;$mpq$;
  EXCEPTION WHEN OTHERS THEN x_post := 'ERR ' || SQLSTATE || ' ' || left(SQLERRM, 300);
  END;
  RETURN pg_temp.all_of(
    pg_temp.pass(x = jsonb_build_object('md5', 'cc2810ee59467829f60d2a9e61455b6c', 'secdef', true, 'vol', 'v', 'config', 'search_path=""', 'owner', 'postgres',
                                        'execute', '["anon", "postgres"]'::jsonb, 'public_execute', false,
                                        't_owner', 'postgres', 't_rls', true, 't_force', false, 't_triggers', 0), 'catalogue ' || x::text),
    pg_temp.pass(x_post = 'ok', 'the migration''s own post-check: ' || x_post));
END $c$;

-- ---------------------------------------------------------------- re-runs: this migration again is a no-op; 20261118180000 again refuses
CREATE FUNCTION pg_temp.c_reruns() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE x_new text := 'ok'; x_old text := 'applied'; x_app text := 'applied'; x_md5a text; x_md5b text; x_md5c text;
BEGIN
  BEGIN
    EXECUTE (SELECT v FROM pg_temp.t66_txt WHERE k = 'm20261123170000');
  EXCEPTION WHEN OTHERS THEN x_new := 'ERR ' || SQLSTATE || ' ' || left(SQLERRM, 300);
  END;
  SELECT md5(prosrc) INTO x_md5a FROM pg_proc WHERE oid = 'public.mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)'::regprocedure;
  BEGIN
    EXECUTE (SELECT v FROM pg_temp.t66_txt WHERE k = 'm20261118180000');
  EXCEPTION WHEN OTHERS THEN x_old := SQLSTATE || ' ' || left(SQLERRM, 300);
  END;
  SELECT md5(prosrc) INTO x_md5b FROM pg_proc WHERE oid = 'public.mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)'::regprocedure;
  BEGIN
    EXECUTE (SELECT v FROM pg_temp.t66_txt WHERE k = 'a20261118180000');
  EXCEPTION WHEN OTHERS THEN x_app := SQLSTATE || ' ' || left(SQLERRM, 300);
  END;
  SELECT md5(prosrc) INTO x_md5c FROM pg_proc WHERE oid = 'public.mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)'::regprocedure;
  RETURN pg_temp.all_of(
    pg_temp.pass(x_new = 'ok' AND x_md5a = 'cc2810ee59467829f60d2a9e61455b6c', 're-run of 20261123170000: ' || x_new || ' md5 ' || coalesce(x_md5a, 'null')),
    -- 20261118180000:36-37: the pre-check accepts only ab6a9345... and 9a33bff2...
    pg_temp.pass(x_old LIKE 'P0001 BACKLOG-4263: public.mcp_exchange_code is not at the expected body%' AND x_md5b = 'cc2810ee59467829f60d2a9e61455b6c',
                 're-run of 20261118180000: ' || x_old || ' md5 ' || coalesce(x_md5b, 'null')),
    pg_temp.pass(x_app LIKE 'P0001 BACKLOG-4263: public.mcp_exchange_code is not at the expected body%' AND x_md5c = 'cc2810ee59467829f60d2a9e61455b6c',
                 're-run of backlog-4263-notice/apply-20261118180000.sql: ' || x_app || ' md5 ' || coalesce(x_md5c, 'null')));
END $c$;

-- ---------------------------------------------------------------- the production post-check of this version, read-only, run as written
-- supabase/tests/backlog-4263-prod/postcheck-20261123170000.sql answers 'ok' or raises (its MUST HOLD rows include the
-- provider CHECK parity of ai_app_connect_notices and mcp_connections)
CREATE FUNCTION pg_temp.c_postcheck() RETURNS text LANGUAGE plpgsql AS $c$
-- The file pins the state after every earlier lane migration, 20261123150000 included (production applies 150000
-- first). On a database where 150000 is not applied it must fail with exactly ONE difference, the one 150000 makes:
-- mcp_list_my_connection_access() absent from the authenticated-callable list. Any other difference (the provider CHECK
-- parity among them) is a FAIL in both states.
DECLARE x_ok text; x_rep text; x_err text; x_150 boolean;
BEGIN
  x_150 := EXISTS (SELECT 1 FROM supabase_migrations.schema_migrations WHERE version = '20261123150000');
  BEGIN
    EXECUTE $pcq$WITH
fn(sig, md5, owner, secdef, vol, lang, config, ret, strict, leak, par) AS (VALUES
    ('public.mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)', 'cc2810ee59467829f60d2a9e61455b6c', 'postgres', 'true', 'v', 'plpgsql', 'search_path=""', 'jsonb', 'false', 'false', 'u')),
fx(sig, role, want, kind) AS (VALUES
    ('public.mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)', 'PUBLIC', 'false', 'function execute api role'),
    ('public.mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)', 'anon', 'true', 'function execute api role'),
    ('public.mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)', 'authenticated', 'false', 'function execute api role'),
    ('public.mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)', 'service_role', 'false', 'function execute api role'),
    ('public.mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)', 'mcp_reader', 'false', 'function execute api role'),
    ('public.mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)', '*', '', 'grants to other roles')),
gone(sig) AS (SELECT NULL::text WHERE false),
rel(name, kind, owner, rls, cols, seqtype) AS (SELECT NULL::text, NULL::text, NULL::text, NULL::text, NULL::text, NULL::text WHERE false),
rx(name, src, role, want, kind) AS (SELECT NULL::text, NULL::text, NULL::text, NULL::text, NULL::text WHERE false),
col(tbl, name, want) AS (SELECT NULL::text, NULL::text, NULL::text WHERE false),
con(tbl, name, want) AS (SELECT NULL::text, NULL::text, NULL::text WHERE false),
cdef(tbl, name, want) AS (SELECT NULL::text, NULL::text, NULL::text WHERE false),
idx(name, want) AS (SELECT NULL::text, NULL::text WHERE false),
ipred(name, want) AS (SELECT NULL::text, NULL::text WHERE false),
job(name, want) AS (SELECT NULL::text, NULL::text WHERE false),
led(version) AS (VALUES
    ('20261123170000')),
anon_want(sig) AS (VALUES
    ('public.mcp_add_todo(text,bytea,text,text,text,text,text,text)'),
    ('public.mcp_authorize_begin(text,text,text,text,text,text,text,text,bytea,bytea)'),
    ('public.mcp_check_access(text,bytea,text)'),
    ('public.mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)'),
    ('public.mcp_find_people(text,bytea,text,text,text,text,text,text,text)'),
    ('public.mcp_get_deal(text,bytea,text,text)'),
    ('public.mcp_get_deal_checklists(text,bytea,text,text,boolean,text)'),
    ('public.mcp_get_message(text,bytea,text,text,integer)'),
    ('public.mcp_get_status(text,bytea,text)'),
    ('public.mcp_list_all_deals(text,bytea,text,text,text,text,text)'),
    ('public.mcp_list_deal_messages(text,bytea,text,text,text,text,integer,text)'),
    ('public.mcp_list_deals(text,bytea,text,text,text,integer,text)'),
    ('public.mcp_list_todos(text,bytea,text,text,text,text,text,boolean,boolean,text)'),
    ('public.mcp_message_access(text,bytea,text)'),
    ('public.mcp_refresh(text,bytea,text,text,bytea,bytea)'),
    ('public.mcp_register_client(text,text,text,text[],bytea)'),
    ('public.mcp_remove_todo(text,bytea,text,text,text)'),
    ('public.mcp_restore_todo(text,bytea,text,text,text)'),
    ('public.mcp_update_todo(text,bytea,text,text,jsonb,text)'),
    ('public.mcp_write_access(text,bytea,text)')),
auth_want(sig) AS (VALUES
    ('public.mcp_authorize_approve(text,bytea,text,bytea)'),
    ('public.mcp_authorize_deny(text,bytea,text)'),
    ('public.mcp_authorize_view(text,bytea)'),
    ('public.mcp_disconnect(uuid)'),
    ('public.mcp_disconnect_all_mine()'),
    ('public.mcp_list_my_connection_access()'),
    ('public.mcp_list_my_connections()'),
    ('public.mcp_list_my_message_reads(text,integer)')),
sweep_want(sig) AS (SELECT NULL::text WHERE false),
trg(name, tbl, want) AS (SELECT NULL::text, NULL::text, NULL::text WHERE false),
dat(name, want) AS (VALUES
    ('provider CHECK of ai_app_connect_notices = mcp_connections', 'equal')),
rule(kind, must) AS (VALUES
    ('anon-callable list', true),
    ('authenticated-callable list', true),
    ('check definition text', false),
    ('column', true),
    ('constraint', true),
    ('cron job', true),
    ('data value', true),
    ('function config', true),
    ('function execute api role', true),
    ('function exists', true),
    ('function language', true),
    ('function leakproof', true),
    ('function md5', true),
    ('function owner', true),
    ('function parallel', true),
    ('function returns', true),
    ('function security_definer', true),
    ('function strict', true),
    ('function volatility', true),
    ('grants to other roles', false),
    ('index', true),
    ('index predicate text', false),
    ('internal-prefix sweep', true),
    ('ledger row', true),
    ('pre-lane table grants api role', true),
    ('pre-lane table grants to service_role', false),
    ('relation columns', true),
    ('relation force_rls', true),
    ('relation grants api role', true),
    ('relation kind', true),
    ('relation owner', true),
    ('relation policies', true),
    ('relation rls', true),
    ('relation sequence type', true),
    ('relation triggers', true)),
checks(id, kind, want, got) AS (
  SELECT 'function ' || substr(e.sig, 8) || ' ' || x.attr, 'function ' || x.attr, x.want, x.got
    FROM fn e
    LEFT JOIN pg_catalog.pg_proc p ON p.oid = pg_catalog.to_regprocedure(e.sig)
    CROSS JOIN LATERAL (VALUES
      ('exists', 'true', (p.oid IS NOT NULL)::text),
      ('md5', e.md5, md5(p.prosrc)),
      ('owner', e.owner, p.proowner::regrole::text),
      ('security_definer', e.secdef, p.prosecdef::text),
      ('volatility', e.vol, p.provolatile::text),
      ('language', e.lang, (SELECT l.lanname::text FROM pg_catalog.pg_language l WHERE l.oid = p.prolang)),
      ('config', e.config, array_to_string(p.proconfig, ',')),
      ('returns', e.ret, pg_catalog.format_type(p.prorettype, NULL)),
      ('strict', e.strict, p.proisstrict::text),
      ('leakproof', e.leak, p.proleakproof::text),
      ('parallel', e.par, p.proparallel::text)) x(attr, want, got)
   WHERE x.attr = 'exists' OR p.oid IS NOT NULL
  UNION ALL
  SELECT 'function ' || substr(f.sig, 8) || ' execute ' || CASE WHEN f.role = '*' THEN 'other roles' ELSE f.role END, f.kind, f.want,
         CASE WHEN f.role = '*' THEN
           coalesce((SELECT string_agg(z.r, ',' ORDER BY z.r COLLATE "C") FROM (SELECT DISTINCT a.grantee::regrole::text AS r FROM pg_catalog.aclexplode(coalesce(p.proacl, pg_catalog.acldefault('f', p.proowner))) a
                      WHERE a.privilege_type = 'EXECUTE' AND a.grantee <> 0 AND a.grantee <> p.proowner
                        AND a.grantee::regrole::text <> ALL (ARRAY['anon', 'authenticated', 'service_role', 'mcp_reader'])) z), '')
         ELSE EXISTS (SELECT 1 FROM pg_catalog.aclexplode(coalesce(p.proacl, pg_catalog.acldefault('f', p.proowner))) a WHERE a.privilege_type = 'EXECUTE' AND a.grantee = CASE f.role WHEN 'PUBLIC' THEN 0::oid ELSE pg_catalog.to_regrole(f.role)::oid END)::text END
    FROM fx f JOIN pg_catalog.pg_proc p ON p.oid = pg_catalog.to_regprocedure(f.sig)
  UNION ALL
  SELECT 'function ' || substr(g.sig, 8) || ' exists', 'function exists', 'false', (pg_catalog.to_regprocedure(g.sig) IS NOT NULL)::text FROM gone g
  UNION ALL
  SELECT 'relation ' || r.name || ' ' || x.attr, 'relation ' || x.attr, x.want, x.got
    FROM rel r
    LEFT JOIN pg_catalog.pg_class c ON c.oid = pg_catalog.to_regclass('public.' || r.name)
    CROSS JOIN LATERAL (VALUES
      ('kind', r.kind, c.relkind::text),
      ('owner', r.owner, c.relowner::regrole::text),
      ('rls', CASE WHEN r.kind = 'r' THEN r.rls END, CASE WHEN r.kind = 'r' THEN c.relrowsecurity::text END),
      ('force_rls', CASE WHEN r.kind = 'r' THEN 'false' END, CASE WHEN r.kind = 'r' THEN c.relforcerowsecurity::text END),
      ('triggers', CASE WHEN r.kind = 'r' THEN '' END, CASE WHEN r.kind = 'r' THEN coalesce((SELECT string_agg(t.tgname::text, ',' ORDER BY t.tgname::text COLLATE "C")
                                                                  FROM pg_catalog.pg_trigger t WHERE t.tgrelid = c.oid AND NOT t.tgisinternal), '') END),
      ('policies', CASE WHEN r.kind = 'r' THEN '' END, CASE WHEN r.kind = 'r' THEN coalesce((SELECT string_agg(y.polname::text, ',' ORDER BY y.polname::text COLLATE "C")
                                                                  FROM pg_catalog.pg_policy y WHERE y.polrelid = c.oid), '') END),
      ('columns', CASE WHEN r.kind = 'r' THEN r.cols END, CASE WHEN r.kind = 'r' THEN (SELECT string_agg(a.attname::text || ' ' || pg_catalog.format_type(a.atttypid, a.atttypmod)
                                                                  || CASE WHEN a.attnotnull THEN ' not null' ELSE '' END, ', ' ORDER BY a.attnum)
                                                             FROM pg_catalog.pg_attribute a WHERE a.attrelid = c.oid AND a.attnum > 0 AND NOT a.attisdropped) END),
      ('sequence type', CASE WHEN r.kind = 'S' THEN r.seqtype END, CASE WHEN r.kind = 'S' THEN (SELECT pg_catalog.format_type(q.seqtypid, NULL)
