)
SELECT CASE WHEN f.must IS NULL THEN 'ok'
            ELSE ('POSTCHECK 20261123170000 FAILED: ' || f.must || ' || REPORT ONLY: ' || coalesce(f.rep, 'none'))::integer::text END AS postcheck,
       coalesce(f.rep, '') AS report_only
  FROM (SELECT string_agg(d.line, ' | ' ORDER BY d.id COLLATE "C") FILTER (WHERE d.must) AS must,
               string_agg(d.line, ' | ' ORDER BY d.id COLLATE "C") FILTER (WHERE NOT d.must) AS rep
          FROM (SELECT c.id, coalesce(r.must, true) AS must,
                       c.id || ': want ' || coalesce(c.want, '(null)') || ', got ' || coalesce(c.got, '(null)') AS line
                  FROM checks c LEFT JOIN rule r ON r.kind = c.kind
                 WHERE c.got IS DISTINCT FROM c.want) d) f$pcq$ INTO x_ok, x_rep;
  EXCEPTION WHEN OTHERS THEN x_err := SQLSTATE || ' ' || SQLERRM;
  END;
  IF x_150 THEN
    RETURN pg_temp.pass(x_err IS NULL AND x_ok = 'ok', '150000 applied; postcheck-20261123170000.sql: ' || left(coalesce(x_err, x_ok || ' / ' || coalesce(x_rep, '')), 600));
  END IF;
  RETURN pg_temp.pass(x_err = '22P02 invalid input syntax for type integer: "POSTCHECK 20261123170000 FAILED: authenticated-callable mcp_ functions: '
                              || 'want missing: none; extra: none, got missing: mcp_list_my_connection_access(); extra: none || REPORT ONLY: none"',
                      '150000 not applied; postcheck-20261123170000.sql: ' || left(coalesce(x_err, x_ok || ' / ' || coalesce(x_rep, '')), 600));
END $c$;
-- catalogue fingerprint of what the mutants change: the exchange (body md5, ACL, volatility, security definer, owner,
-- settings), the notice table (owner, ACL, RLS, FORCE RLS), its constraint names, the non-internal triggers on it and on
-- mcp_connections, and the stored migration texts. Every operand is cast to text explicitly; ACL items are sorted; a
-- NULL ACL reads 'acl:default'.
CREATE FUNCTION pg_temp.fingerprint() RETURNS text LANGUAGE sql VOLATILE AS $h$
  SELECT md5(concat_ws('|',
    (SELECT concat_ws(':', p.oid::regprocedure::text, md5(p.prosrc)::text,
                      CASE WHEN p.proacl IS NULL THEN 'acl:default' ELSE (SELECT string_agg(x.item::text, ',' ORDER BY x.item::text) FROM unnest(p.proacl) AS x(item)) END,
                      p.provolatile::text, p.prosecdef::text, pg_catalog.pg_get_userbyid(p.proowner)::text, coalesce(array_to_string(p.proconfig, ','), '')::text)
       FROM pg_catalog.pg_proc p WHERE p.oid = to_regprocedure('public.mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)')),
    (SELECT concat_ws(':', pg_catalog.pg_get_userbyid(c.relowner)::text,
                      CASE WHEN c.relacl IS NULL THEN 'acl:default' ELSE (SELECT string_agg(x.item::text, ',' ORDER BY x.item::text) FROM unnest(c.relacl) AS x(item)) END,
                      c.relrowsecurity::text, c.relforcerowsecurity::text)
       FROM pg_catalog.pg_class c WHERE c.oid = 'public.ai_app_connect_notices'::regclass),
    (SELECT string_agg(k.conname::text, ',' ORDER BY k.conname::text) FROM pg_catalog.pg_constraint k WHERE k.conrelid = 'public.ai_app_connect_notices'::regclass),
    (SELECT coalesce(string_agg(t.tgrelid::regclass::text || '.' || t.tgname::text, ',' ORDER BY t.tgrelid::regclass::text, t.tgname::text), '')
       FROM pg_catalog.pg_trigger t WHERE t.tgrelid IN ('public.ai_app_connect_notices'::regclass, 'public.mcp_connections'::regclass) AND NOT t.tgisinternal),
    (SELECT string_agg(x.k || '=' || md5(x.v), ',' ORDER BY x.k) FROM pg_temp.t66_txt x)))
$h$;
DO $controls4266$
DECLARE res text; base jsonb := '{}'; o jsonb; applied boolean;
BEGIN
  PERFORM pg_temp.rec('t_start', to_jsonb(clock_timestamp()));
  PERFORM pg_temp.rec('baseline_fp', to_jsonb(pg_temp.fingerprint()));
  PERFORM pg_temp.rec('mode', to_jsonb('structure'::text));
    BEGIN
      res := pg_temp.c_notice();
      RAISE EXCEPTION 'undo-case';
    EXCEPTION WHEN OTHERS THEN
      IF SQLERRM <> 'undo-case' THEN res := 'ERROR ' || SQLSTATE || ' ' || left(SQLERRM, 400); END IF;
    END;
    base := base || jsonb_build_object('c_notice', res);
  PERFORM pg_temp.rec('controls', base);
  PERFORM pg_temp.rec('t_controls_end', to_jsonb(clock_timestamp()));
  -- M01_swallow_restored
  BEGIN
    o := '{}';
    applied := NULL;
    EXECUTE $mu0$CREATE OR REPLACE FUNCTION public.mcp_exchange_code(p_secret text, p_code_digest bytea, p_code_verifier text, p_client_id text, p_redirect_uri text,
                                                    p_resource text, p_at_digest bytea, p_rt_digest bytea)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = '' AS $fn$
DECLARE
  v_code   public.mcp_authorization_codes%ROWTYPE;
  v_used   public.mcp_authorization_codes%ROWTYPE;
  v_user   uuid;
  v_redir  text;
  v_pepper smallint;
  v_n      integer;
  v_scope  text;
BEGIN
  /*BODY:4263-10.7*/
  IF public._mcp_secret_ok(p_secret) IS NOT TRUE THEN
    RETURN public._mcp_refuse('invalid_grant');
  END IF;
  IF (octet_length(p_code_digest) = 32 AND octet_length(p_at_digest) = 32 AND octet_length(p_rt_digest) = 32
      AND p_at_digest IS DISTINCT FROM p_rt_digest) IS NOT TRUE THEN
    RETURN public._mcp_token_fail(p_client_id, 'invalid_request');
  END IF;

  -- token insert failure: everything in this block is rolled back (code not used up)
  BEGIN
  UPDATE public.mcp_authorization_codes k
     SET used_at = now()
   WHERE k.code_sha256 = sha256(p_code_digest)
     AND k.used_at IS NULL
     AND k.expires_at > now()
  RETURNING k.* INTO v_code;

  IF v_code.code_sha256 IS NULL THEN
    -- a used code presented again: the connection is removed only when the request is otherwise
    -- valid for that code (client, verifier, and redirect address when sent)
    SELECT k.* INTO v_used
      FROM public.mcp_authorization_codes k
     WHERE k.code_sha256 = sha256(p_code_digest)
       AND k.used_at IS NOT NULL;
    IF v_used.code_sha256 IS NOT NULL THEN
      SELECT c.user_id INTO v_user FROM public.mcp_connections c WHERE c.id = v_used.connection_id;
      IF (v_used.client_id = p_client_id
          AND (p_redirect_uri IS NULL OR v_used.redirect_uri = p_redirect_uri)
          AND p_code_verifier ~ '^[A-Za-z0-9._~-]{43,128}$'
          AND public._mcp_b64url(sha256(convert_to(p_code_verifier, 'UTF8'))) = v_used.code_challenge) IS TRUE THEN
        DELETE FROM public.mcp_connections c WHERE c.id = v_used.connection_id;
        INSERT INTO public.mcp_call_log (user_id, connection_id, event, outcome, ended_at)
        VALUES (v_user, v_used.connection_id, 'code_replay', 'ok', now());
      ELSIF public._mcp_bump('replay_refused:' || v_used.connection_id::text, interval '1 hour', 5) IS NOT DISTINCT FROM 'ok' THEN
        -- at most 5 refused-replay events per connection per hour; the response is the same either way
        INSERT INTO public.mcp_call_log (user_id, connection_id, event, outcome, ended_at)
        VALUES (v_user, v_used.connection_id, 'code_replay_refused', 'ok', now());
      END IF;
    END IF;
    RETURN public._mcp_token_fail(p_client_id, 'invalid_grant');
  END IF;

  -- a rejected redemption uses up the code and removes its pending connection
  IF (v_code.client_id = p_client_id
      AND (p_redirect_uri IS NULL OR v_code.redirect_uri = p_redirect_uri)
      AND v_code.resource = p_resource
      AND EXISTS (SELECT 1 FROM public.mcp_redirect_allowlist a WHERE a.redirect_uri = v_code.redirect_uri)
      AND p_code_verifier ~ '^[A-Za-z0-9._~-]{43,128}$'
      AND public._mcp_b64url(sha256(convert_to(p_code_verifier, 'UTF8'))) = v_code.code_challenge) IS NOT TRUE THEN
    DELETE FROM public.mcp_connections c
     WHERE c.id = v_code.connection_id AND c.status = 'pending'
    RETURNING c.user_id INTO v_user;
    INSERT INTO public.mcp_call_log (user_id, connection_id, event, outcome, ended_at)
    VALUES (v_user, v_code.connection_id, 'code_rejected', 'ok', now());
    RETURN public._mcp_token_fail(p_client_id, 'invalid_grant');
  END IF;

  UPDATE public.mcp_connections c
     SET status = 'active', activated_at = now()
   WHERE c.id = v_code.connection_id
     AND c.status = 'pending'
  RETURNING c.user_id, c.redirect_uri, c.scope INTO v_user, v_redir, v_scope;
  IF v_user IS NULL THEN
    RETURN public._mcp_refuse('invalid_grant');
  END IF;

  DELETE FROM public.mcp_connections c
   WHERE c.user_id = v_user AND c.redirect_uri = v_redir AND c.id <> v_code.connection_id AND c.status = 'active';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n > 0 THEN
    INSERT INTO public.mcp_call_log (user_id, connection_id, event, outcome, ended_at, rows_returned)
    VALUES (v_user, v_code.connection_id, 'reconnect_replaced', 'ok', now(), v_n);
  END IF;

  SELECT s.pepper_version INTO v_pepper FROM public.mcp_settings s WHERE s.id;
  BEGIN
    INSERT INTO public.mcp_tokens (token_sha256, connection_id, kind, pepper_version, expires_at) VALUES
      (sha256(p_at_digest), v_code.connection_id, 'access', v_pepper, now() + interval '1 hour'),
      (sha256(p_rt_digest), v_code.connection_id, 'refresh', v_pepper, now() + interval '30 days');
  EXCEPTION WHEN unique_violation OR not_null_violation THEN
    RAISE EXCEPTION USING ERRCODE = 'MC001', MESSAGE = 'mcp token insert failed';
  END;
  -- 4263 PR-10.7: one notice for the connection that just turned active, read later by the email job. In its own
  -- block: any error here discards the notice only; the exchange and its answer are unchanged.
  BEGIN
    INSERT INTO public.ai_app_connect_notices (user_id, provider, replaced)
    SELECT c.user_id, c.provider, v_n > 0 FROM public.mcp_connections c WHERE c.id = v_code.connection_id;   /*NOTICE:exchange*/
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;
  RETURN jsonb_build_object('ok', true, 'token_type', 'Bearer', 'expires_in', 3600, 'scope', v_scope);   /*SCOPE:exchange*/
  EXCEPTION WHEN SQLSTATE 'MC001' THEN
    RETURN public._mcp_token_fail(p_client_id, 'invalid_request');
  END;
END
$fn$;$mu0$;
    applied := (SELECT md5(prosrc)::text FROM pg_catalog.pg_proc WHERE oid = to_regprocedure('public.mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)')) = '9a33bff2db31288bd77a57489558a65b';
    IF applied IS NOT TRUE THEN RAISE EXCEPTION 'MUTATION NOT APPLIED IN DB'; END IF;
    BEGIN
      res := pg_temp.c_fail_check();
      RAISE EXCEPTION 'undo-case';
    EXCEPTION WHEN OTHERS THEN
      IF SQLERRM <> 'undo-case' THEN res := 'ERROR ' || SQLSTATE || ' ' || left(SQLERRM, 400); END IF;
    END;
    o := o || jsonb_build_object('c_fail_check', res);
