  IF (v ->> 'exchange')::boolean IS NOT TRUE OR (v ->> 'ledger')::int IS DISTINCT FROM 0 THEN
    RAISE EXCEPTION 'ROLLBACK POST-CHECK 20261123170000 FAILED, nothing changed: %', v;
  END IF;
END
