    PERFORM pg_temp.rec('rollback', to_jsonb('ok'::text));
  EXCEPTION WHEN OTHERS THEN
    PERFORM pg_temp.rec('rollback', to_jsonb('ERROR ' || SQLSTATE || ' ' || left(SQLERRM, 900)));
  END;
END
