BEGIN
  PERFORM pg_temp.rec('rb_state', jsonb_build_object(
    'exchange_md5', (SELECT md5(prosrc)::text FROM pg_catalog.pg_proc WHERE oid = to_regprocedure('public.mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)')),
    'same_as_before_apply', (SELECT a.src_md5 = b.src_md5 AND a.acl IS NOT DISTINCT FROM b.acl AND a.config = b.config AND a.secdef = b.secdef
                                    AND a.owner = b.owner AND a.vol = b.vol
                               FROM (  SELECT p.oid::regprocedure::text AS sig, md5(p.prosrc)::text AS src_md5, p.proacl::text AS acl, coalesce(array_to_string(p.proconfig, ','), '')::text AS config,
         p.prosecdef AS secdef, pg_catalog.pg_get_userbyid(p.proowner)::text AS owner, p.provolatile::text AS vol
    FROM pg_catalog.pg_proc p WHERE p.pronamespace = 'public'::regnamespace) a JOIN pg_temp.t66_fn_before b ON b.sig = a.sig WHERE a.sig = 'public.mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)'::regprocedure::text),
    'ledger', (SELECT count(*) FROM supabase_migrations.schema_migrations WHERE version = '20261123170000')));
  x_c := pg_temp.consent('n-rb', pg_temp.id('C'), 'anthropic');
  x_e := pg_temp.w(pg_temp.q_ex('n-rb', 'anthropic', 301));
